/**
 * Account-funded web research tools. Each one calls the matching Bearer route
 * (/v1/tools/<slug>) generated by the server's defineProxyService. Input JSON
 * schemas are copied verbatim from the server definitions (a server contract
 * test keeps them identical); the server validates the body and returns 400
 * before any payment, so the MCP side only checks that arguments are an object.
 */
export type WebResearchTool = {
  name: string;
  /** paidCalls.tool / /v1/tools/prices id on the server. */
  serverToolId: string;
  path: string;
  priceUsdc: string;
  description: string;
  inputSchema: Record<string, unknown>;
};

