export type WebResearchToolName = (typeof webResearchTools)[number]["name"];

export const webResearchToolDefinitions = webResearchTools.map(tool => ({
  name: tool.name,
  description: tool.description,
  inputSchema: tool.inputSchema,
}));

export const webResearchInputSchema = z.record(z.unknown());

export function findWebResearchTool(name: string): WebResearchTool | undefined {
  return webResearchTools.find(tool => tool.name === name);
}

export async function webResearchCall(api: ApiClient, toolName: string, args: unknown): Promise<unknown> {
  const tool = findWebResearchTool(toolName);
  if (!tool) throw new Error(`Unknown web research tool: ${toolName}`);
  const input = webResearchInputSchema.parse(args ?? {});
  const res = await fetch(`${api.apiBaseUrl}${tool.path}`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "idempotency-key": randomUUID(),
      ...api.authHeader(),
    },
    body: JSON.stringify(input),
  });
  if (!res.ok) throw new Error(`${tool.name} failed ${res.status}: ${await res.text()}`);
  return res.json();
}
